#include "decision_engine.h"
#include "config.h"
void DecisionEngine::begin(){current=SystemState::SELF_TEST;}
const char*DecisionEngine::name(SystemState s){switch(s){case SystemState::STARTUP:return"STARTUP";case SystemState::SELF_TEST:return"SELF_TEST";case SystemState::MONITORING:return"MONITORING";case SystemState::POSSIBLE_OBSTRUCTION:return"POSSIBLE_OBSTRUCTION";case SystemState::WASTE_DETECTED:return"WASTE_DETECTED";case SystemState::DIVERSION_REQUESTED:return"DIVERSION_REQUESTED";case SystemState::DIVERTING:return"DIVERTING";case SystemState::RECOVERY:return"RECOVERY";case SystemState::SENSOR_FAULT:return"SENSOR_FAULT";case SystemState::CAMERA_FAULT:return"CAMERA_FAULT";case SystemState::SAFE_MODE:return"SAFE_MODE";}return"UNKNOWN";}
Decision DecisionEngine::update(const DistanceReading&d,const WaterReading&w,bool cameraReady,bool cameraFault,const Prediction&p,bool manual){bool request=false,candidate=false;if(!d.valid||!w.valid){current=SystemState::SENSOR_FAULT;nearCount=0;return{current,false,false};}if(cameraFault){current=SystemState::CAMERA_FAULT;nearCount=0;return{current,false,false};}bool near=d.cm>0&&d.cm<Config::OBSTRUCTION_DISTANCE_CM;nearCount=near?min<uint8_t>(nearCount+1,255):0;bool pred=cameraReady&&p.valid&&!p.mock&&p.confidence>=Config::MIN_AI_CONFIDENCE;candidate=pred;if(pred){current=SystemState::WASTE_DETECTED;if(nearCount>=Config::CONFIRM_COUNT&&(!Config::ACTUATOR_REQUIRE_WATER_WET||w.wet)&&Config::ACTUATOR_ENABLED&&!Config::ACTUATOR_TEST_ONLY){current=SystemState::DIVERSION_REQUESTED;request=true;}}else if(manual){current=SystemState::DIVERSION_REQUESTED;request=Config::ACTUATOR_ENABLED&&!Config::ACTUATOR_TEST_ONLY;}else if(nearCount>=Config::CONFIRM_COUNT)current=SystemState::POSSIBLE_OBSTRUCTION;else current=SystemState::MONITORING;return{current,request,candidate};}
